      "id": "cmd-modprobe",
      "label": "modprobe",
      "type": "command",
      "exam": "101",
      "tema": "101",
      "subtopic_id": "101.1",
      "title": "Comando: modprobe",
      "desc": "modprobe resuelve dependencias leyendo modules.dep; insmod es de bajo nivel y no gestiona dependencias:",
      "syntax": "sudo modprobe -v usb_storage",
      "flags": [
        {
          "flag": "modprobe <mod>",
          "desc": "Carga automática con dependencias de modules.dep."
        },
        {
          "flag": "-r / --remove",
          "desc": "🎯 Examen: Descarga el módulo y sus dependencias no usadas."
        },
        {
          "flag": "-v / --verbose",
          "desc": "Muestra los insmod ejecutados en orden de dependencia."
        },
        {
          "flag": "-c / --showconfig",
          "desc": "Muestra la unión consolidada de /etc/ y /lib/."
        }
      ],
      "examples": [
        "sudo modprobe -v usb_storage"
      ],
      "exam_tips": [
        {
          "q_num": 99,
          "exam": "101",
          "stem": "Which of the following commands loads a kernel module along with any required dependency modules?",
          "answer": "modprobe",
          "explanation": "A diferencia de insmod (que carga únicamente el archivo .ko indicado y falla si faltan dependencias), modprobe ( man 8 modprobe ) consulta modules.dep y carga de forma inteligente el módulo solicitado junto con todos los módulos de los que depende."
        },
        {
          "q_num": 106,
          "exam": "101",
          "stem": "A faulty kernel module is causing issues with a network interface card. Which of the following actions ensures that this module is not loaded automatically when...",
          "answer": "Adding a blacklist line including the name of the offending module to the file / etc/modprobe.d/blacklist.conf.",
          "explanation": "Según man 5 modprobe.d , añadir la directiva blacklist en un archivo .conf dentro de /etc/modprobe.d/ hace que se ignoren todos los alias internos del módulo, evitando que udev / modprobe lo carguen automáticamente al detectar el hardware durante el arranque."
        }
      ],
      "slide_url": "t101/101-1-determinar-y-configurar.html#/8",
