      "id": "cmd-dmesg",
      "label": "dmesg",
      "type": "command",
      "exam": "101",
      "tema": "101",
      "subtopic_id": "101.2",
      "title": "Comando: dmesg",
      "desc": "Inspeccionar el historial de detección de hardware en la memoria RAM con el comando dmesg",
      "syntax": "dmesg -T -l err,warn",
      "flags": [
        {
          "flag": "¿Para qué sirve dmesg en la vida real?",
          "desc": "Es la primera herramienta del SysAdmin cuando algo de hardware falla: un disco que da errores de lectura, una tarjeta Wi-Fi que no conecta o un puerto USB que no reconoce un dispositivo."
        },
        {
          "flag": "dmesg -T (Human-readable time)",
          "desc": "🎯 Clave de Examen: Convierte los segundos incomprensibles [  12.451234] en fechas y horas humanas reales (ej: 'Sun Oct 25 10:14:02 2026')."
        },
        {
          "flag": "dmesg -l err,warn",
          "desc": "Filtra la salida para no leer miles de líneas y ver únicamente los errores y advertencias de hardware."
        },
        {
          "flag": "dmesg -w (Follow / En vivo)",
          "desc": "Se queda a la escucha en directo (como tail -f): conectas un pendrive USB y ves salir los mensajes del kernel al instante."
        }
      ],
      "examples": [
        "dmesg -T -l err,warn"
      ],
      "exam_tips": [
        {
          "q_num": 16,
          "exam": "101",
          "stem": "When is the content of the kernel ring buffer reset? (Choose two.)",
          "answer": "When the ring buffer is explicitly reset using the command dmesg --clear. y When the system is shut down or rebooted.",
          "explanation": "El kernel ring buffer se almacena en memoria RAM volátil, por lo que su contenido desaparece cuando el sistema se apaga o reinicia. Asimismo, se puede vaciar manualmente en cualquier momento ejecutando dmesg --clear (o dmesg -C ), según man 1 dmesg ."
        },
        {
          "q_num": 116,
          "exam": "101",
          "stem": "When booting from the hard disk, a computer successfully loads the Linux kernel and initramfs but hangs during th e subsequent startup tasks. The system is boot...",
          "answer": "Investigating the file /var/log on the computer's hard disk for possible errors.",
          "explanation": "dmesg y /proc/kmsg muestran únicamente los mensajes en memoria del kernel actualmente en ejecución (es decir, el del CD de rescate, incluso si se hace chroot ). Como el sistema original ya había superado la fase de initramfs y estaba ejecutando las tareas de inicio sobre el disco duro, los registros..."
        }
      ],
      "slide_url": "t101/101-2-arranque-del-sistema.html#/10",
      "practice_url": "practicas/p-101-2-arranque-sistema.html",
      "weight": 2
