      "title": "Comando: runlevel",
      "desc": "Consultar el nivel previo y actual, y solicitar la transición hacia un nuevo nivel",
      "syntax": "runlevel [opciones]",
      "flags": [
        {
          "flag": "runlevel",
          "desc": "🎯 Clave de Examen: Muestra dos caracteres: el nivel previo (N = ninguno si no ha cambiado desde el arranque) y el nivel actual."
        },
        {
          "flag": "telinit <0-6>",
          "desc": "Solicita a init cambiar al nivel indicado (ej: telinit 1 pasa a monousuario; telinit 6 reinicia)."
        },
        {
          "flag": "telinit q / Q",
          "desc": "🎯 Clave de Examen: Recarga el archivo /etc/inittab sin necesidad de reiniciar el sistema."
        },
        {
          "flag": "Prefijo 'S' (Start)",
          "desc": "En /etc/rcX.d/, los enlaces que empiezan por S (ej: S01ssh) arrancan el servicio pasando el argumento 'start'."
        },
        {
          "flag": "Prefijo 'K' (Kill)",
          "desc": "Los enlaces que empiezan por K (ej: K01apache2) detienen el servicio pasando el argumento 'stop'."
        }
      ],
      "examples": [],
      "exam_tips": [
        {
          "q_num": 117,
          "exam": "101",
          "stem": "Given the following two symbolic links in a System V init configuration: /etc/rc1.d/K01apache2 and /etc/rc2.d/S02apache2 . When are the scripts executed that ar...",
          "answer": "S02apache2 is run when runlevel 2 is entered. y K01apache2 is run when runlevel 1 is entered.",
          "explanation": "En System V init, cuando se entra en un nivel de ejecución N N N , el sistema recorre el directorio /etc/rcN.d/ ejecutando primero los enlaces que empiezan por K ( Kill , pasando el argumento stop ) y después los enlaces que empiezan por S ( Start , pasando el argumento start ). Por tanto, K01apache..."
        }
      ],
      "slide_url": "t101/101-3-cambiar-los-niveles-de-e.html#/5",
