      "id": "cmd-mkswap",
      "label": "mkswap",
      "type": "command",
      "exam": "101",
      "tema": "102",
      "subtopic_id": "102.1",
      "title": "Comando: mkswap",
      "desc": "¿Qué es la Swap, cómo salva al sistema y los 4 pasos exactos que entran en el examen?",
      "syntax": "mkswap [opciones]",
      "flags": [
        {
          "flag": "mkswap <disp>",
          "desc": "🎯 Clave de Examen: Inicializa y formatea el espacio de swap escribiendo la firma 'SWAPSPACE2' y generando su UUID."
        },
        {
          "flag": "mkswap -L <label>",
          "desc": "Asigna una etiqueta a la partición de swap para montaje amigable."
        },
        {
          "flag": "swapon <disp>",
          "desc": "🎯 Clave de Examen: Activa el área de memoria de intercambio para que el kernel comience a utilizarla."
        },
        {
          "flag": "swapon -a",
          "desc": "🎯 Clave de Examen: Activa TODAS las áreas de swap configuradas en /etc/fstab."
        },
        {
          "flag": "swapon --show (o -s)",
          "desc": "Muestra una tabla con los dispositivos swap activos, tipo, tamaño, uso y prioridad."
        },
        {
          "flag": "swapoff <disp>",
          "desc": "Desactiva el área de swap volcando previamente todas las páginas de memoria de nuevo a la RAM."
        }
      ],
      "examples": [
        "sudo mkswap -L 'SWAP_DISK' /dev/sdb2; sudo swapon /dev/sdb2; swapon --show"
      ],
      "exam_tips": [],
