      "id": "cmd-virt-install",
      "label": "virt-install",
      "type": "command",
      "exam": "101",
      "tema": "102",
      "subtopic_id": "102.6",
      "title": "Comando: virt-install",
      "desc": "Aprovisionar máquinas virtuales desde terminal y gobernar su ciclo de vida en servidores remotos sin entorno gráfico.",
      "syntax": "virt-install [opciones]  |  virsh [list|start|shutdown|destroy|undefine] <vm>",
      "flags": [
        {
          "flag": "virt-install",
          "desc": "🎯 Comando CLI para crear dominios libvirt especificando vCPUs, RAM, disco ISO y red."
        },
        {
          "flag": "virsh list [--all]",
          "desc": "🎯 'virsh list' muestra solo las VMs encendidas; '--all' lista también las apagadas."
        },
        {
          "flag": "virsh start <vm>",
          "desc": "Arranca el dominio libvirt indicado."
        },
        {
          "flag": "virsh shutdown <vm>",
          "desc": "🎯 Envía una señal ACPI al kernel invitado para realizar un apagado limpio y seguro."
        },
        {
          "flag": "virsh destroy <vm>",
          "desc": "🎯 Clave de Examen: Corta la corriente de golpe (hard reset). ¡NO borra el disco ni la VM!"
        }
      ],
