      "exam": "101",
      "tema": "103",
      "subtopic_id": "103.2",
      "title": "Comando: cut",
      "desc": "Recortar campos verticales de texto o unir archivos horizontalmente en columnas",
      "syntax": "cut -d':' -f1,7 <file> | paste -d',' arch1 arch2",
      "flags": [
        {
          "flag": "cut -d<delim>",
          "desc": "🎯 Define el carácter separador de columnas (por defecto tabulador). En /etc/passwd es ':'."
        },
        {
          "flag": "cut -f<campos>",
          "desc": "🎯 Número de columnas a recortar: '-f1' (primera), '-f1,7' (primera y séptima), '-f1-3' (rango)."
        },
        {
          "flag": "cut -c<rango>",
          "desc": "🎯 Extrae por posición fija de caracteres: 'cut -c 1-8' (de la letra 1 a la 8)."
        },
        {
          "flag": "paste arch1 arch2",
          "desc": "🎯 Junta archivos lado a lado, línea 1 con línea 1, línea 2 con línea 2."
        },
        {
          "flag": "paste -s",
          "desc": "Convierte todas las líneas verticales de un mismo archivo en una sola línea horizontal."
        }
      ],
      "examples": [
        "cut -d: -f1,7 /etc/passwd | head -n 3; paste -d',' users.txt shells.txt"
      ],
      "exam_tips": [
        {
          "q_num": 46,
          "exam": "101",
          "stem": "Which of the following commands prints a list of usernames (first column) and their primary group (fourth column) from the /etc/passwd file?",
          "answer": "cut -d : -f 1,4 /etc/passwd",
          "explanation": "El comando cut extrae columnas de archivos de texto. La opción -d : define los dos puntos como delimitador de campos, y -f 1,4 selecciona el primer y cuarto campo de cada línea ( man 1 cut )."
        },
        {
          "q_num": 88,
          "exam": "101",
          "stem": "Which of the following commands generates a list of user names from /etc/passwd along with their login shell?",
          "answer": "cut -d: -f1,7 /etc/passwd",
          "explanation": "En /etc/passwd , los campos están separados por : ( -d: ), donde el campo 1 es el nombre de usuario y el campo 7 es el intérprete de comandos ( login shell ). cut -d: -f1,7 /etc/passwd extrae ambos campos."
        }
      ],
      "slide_url": "t103/103-2-procesar-secuencias-de-t.html#/5",
