      "id": "cmd-ls",
      "label": "ls",
      "type": "command",
      "exam": "101",
      "tema": "103",
      "subtopic_id": "103.3",
      "title": "Comando: ls",
      "desc": "Consultar permisos, propietarios, tamaños reales y metadatos de archivos y carpetas",
      "syntax": "ls -lhd <carpeta> | ls -lai <fichero>",
      "flags": [
        {
          "flag": "ls -l",
          "desc": "🎯 Imprime 8 columnas: tipo, 9 permisos, enlaces, dueño UID, grupo GID, tamaño, fecha y nombre."
        },
        {
          "flag": "ls -a",
          "desc": "🎯 Clave de Examen: Muestra todos los ficheros, incluidos los ocultos que inician por punto (.) y '.' / '..'"
        },
        {
          "flag": "ls -d",
          "desc": "🎯 Clave de Examen: Lista las propiedades de la carpeta en sí, sin entrar a listar su contenido."
        },
        {
          "flag": "ls -h",
          "desc": "🎯 Convierte los bytes en unidades entendibles (K, M, G, T) junto con la opción -l."
        },
        {
          "flag": "ls -i",
          "desc": "🎯 Muestra el identificador numérico de inodo en la primera columna."
        },
        {
          "flag": "ls -t / -S",
          "desc": "'-t' ordena cronológicamente (más recientes primero); '-S' por tamaño descendente."
        },
        {
          "flag": "screen",
          "desc": "Inicia una nueva sesión virtual de GNU Screen."
        },
        {
          "flag": "Ctrl + A y luego d",
          "desc": "🎯 Clave de Examen: Desacopla (Detach) la sesión de Screen dejándola corriendo en segundo plano sin interrumpir los procesos."
        },
        {
          "flag": "screen -r [id]",
          "desc": "🎯 Clave de Examen: Reanuda (Resume / Reattach) una sesión de Screen que fue desacoplada previamente."
        },
        {
          "flag": "screen -ls",
          "desc": "Lista todas las sesiones de Screen activas en el sistema."
        },
        {
          "flag": "Ctrl + B y luego d (tmux)",
          "desc": "🎯 Desacopla la sesión activa en tmux."
        },
        {
          "flag": "tmux attach [-t sesion]",
          "desc": "Reconecta la sesión de tmux indicada."
        }
      ],
      "examples": [
        "ls -ld /var/log; ls -lh /var/log/syslog; ls -lai .bashrc",
        "screen -ls; tmux ls"
      ],
