      "id": "cmd-mkfs",
      "label": "mkfs",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.1",
      "title": "Comando: mkfs",
      "desc": "Crear sistemas de archivos ext2, ext3 o ext4 configurando bloques, inodos y journal",
      "syntax": "sudo mke2fs -t ext4 -L 'DATOS' -m 1 /dev/sdb1",
      "flags": [
        {
          "flag": "mkfs -t <tipo>",
          "desc": "Front-end genérico que llama internamente a mkfs.ext4, mkfs.xfs, mkfs.vfat, etc."
        },
        {
          "flag": "mke2fs -t ext4",
          "desc": "🎯 Comando maestro oficial para la familia ext. Crea sistemas ext2 (-t ext2), ext3 (-t ext3) o ext4 (-t ext4)."
        },
        {
          "flag": "mke2fs -j",
          "desc": "🎯 Clave de Examen: Crea un diario de transacciones (Journal) convirtiendo ext2 en ext3."
        },
        {
          "flag": "-b <1024|2048|4096>",
          "desc": "🎯 Clave de Examen: Especifica el tamaño de bloque en bytes (por defecto 4096 bytes / 4 KB)."
        },
        {
          "flag": "-L <etiqueta>",
          "desc": "Asigna una etiqueta de volumen (Volume Label) de hasta 16 caracteres para montaje amigable."
        },
        {
          "flag": "-m <porcentaje>",
          "desc": "🎯 Clave de Examen: Porcentaje de bloques reservados para el superusuario root (por defecto 5%, se puede bajar a 1% con -m 1)."
        }
      ],
      "examples": [
        "sudo mke2fs -t ext4 -L 'DATOS' -m 1 /dev/sdb1"
      ],
      "exam_tips": [
        {
          "q_num": 1,
          "exam": "101",
          "stem": "Which type of file system is created by mkfs when it is executed with the block device name only and without any additional parameters?",
          "answer": "ext2",
          "explanation": "Según la documentación man 8 mkfs, cuando mkfs se invoca sin especificar el tipo de sistema de archivos mediante el parámetro -t , utiliza por defecto ext2 por razones históricas de compatibilidad con versiones anteriores de util-linux ."
        },
        {
          "q_num": 67,
          "exam": "101",
          "stem": "Which of the following Linux filesystems preallocate a fixed number of inodes when creating a new filesystem instead of generating them as needed? (Choose two.)",
          "answer": "ext3 y ext2",
          "explanation": "Los sistemas de archivos de la familia Extended ( ext2 , ext3 , ext4 ) crean una tabla estática de inodos durante el formateo ( mkfs ), por lo que el número máximo de inodos queda fijado al crear el sistema de archivos (a diferencia de XFS, JFS o Btrfs, que asignan inodos de forma dinámica)."
        }
      ],
      "slide_url": "t104/104-1-creacion-de-particiones.html#/7",
      "practice_url": "practicas/p-104-1-crear-particiones-archivos.html",
      "weight": 2
