      "id": "cmd-xfs_repair",
      "label": "xfs_repair",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.2",
      "title": "Comando: xfs_repair",
      "desc": "Verificar, reparar y desfragmentar sistemas de archivos XFS",
      "syntax": "sudo umount /dev/sdb2; sudo xfs_repair /dev/sdb2",
      "flags": [
        {
          "flag": "xfs_repair <partición>",
          "desc": "🎯 Clave Absoluta de Examen: Herramienta oficial para reparar XFS. ⚠️ ¡Debe ejecutarse SIEMPRE con el sistema de archivos DESMONTADO!"
        },
        {
          "flag": "xfs_repair -n",
          "desc": "🎯 Modo No Modify: solo inspecciona e informa de los fallos encontrados SIN aplicar modificaciones en disco (sustituye a xfs_check)."
        },
        {
          "flag": "xfs_repair -L",
          "desc": "⚠️ ¡Último recurso! Limpia a ceros el log del journal corrupto para permitir arrancar, asumiendo pérdida de últimas escrituras."
        },
        {
          "flag": "xfs_fsr [disp]",
          "desc": "🎯 XFS File System Reorganizer: desfragmentador en línea para XFS (se ejecuta con el sistema MONTADO)."
        }
      ],
      "examples": [
        "sudo umount /dev/sdb2; sudo xfs_repair /dev/sdb2"
      ],
      "exam_tips": [
        {
          "q_num": 70,
          "exam": "101",
          "stem": "After a power outage, the XFS file system of /dev/sda3 is inconsistent. How can the existing file system errors be fixed?",
          "answer": "By running xfs_repair on the file system.",
          "explanation": "La herramienta especializada para comprobar y reparar un sistema de archivos XFS dañado o inconsistente (desmontado) es xfs_repair ( man 8 xfs_repair )."
        }
      ],
      "slide_url": "t104/104-2-mantener-la-integridad-d.html#/9",
      "practice_url": "practicas/p-104-2-integridad-sistemas-archivos.html",
