      "id": "cmd-blkid",
      "label": "blkid",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.3",
      "title": "Comando: blkid",
      "desc": "Averiguar UUIDs, etiquetas y tipos de sistemas de archivos para configuraciones persistentes",
      "syntax": "sudo blkid /dev/sdb1; findfs LABEL=DATOS",
      "flags": [
        {
          "flag": "El peligro /dev/sda",
          "desc": "⚠️ Cambiar el orden de cables o buses altera /dev/sda a /dev/sdb provocando fallo de arranque."
        },
        {
          "flag": "UUID (128 bits)",
          "desc": "🎯 Identificador de 128 bits inmutable que reside en el superbloque. Es idéntico en cualquier bus."
        },
        {
          "flag": "blkid [disp]",
          "desc": "🎯 Clave de Examen: Bloque ID: imprime el UUID, LABEL y TYPE de todas las particiones o del dispositivo indicado."
        },
        {
          "flag": "lsblk -f",
          "desc": "🎯 Muestra un árbol visual limpio con nombres de partición, sistemas de archivos, etiquetas, UUIDs y puntos de montaje."
        },
        {
          "flag": "findfs UUID=<uuid>",
          "desc": "🎯 Clave de Examen: Busca y devuelve la ruta del dispositivo físico que posee ese UUID (ej: '/dev/sdb1')."
        },
        {
          "flag": "findfs LABEL=<label>",
          "desc": "Devuelve la ruta del dispositivo físico que posee esa etiqueta de volumen."
        }
      ],
      "examples": [
        "sudo blkid /dev/sdb1; findfs LABEL=DATOS"
      ],
