      "id": "cmd-locate",
      "label": "locate",
      "type": "command",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.7",
      "title": "Comando: locate",
      "desc": "Consultar la base de datos indexada local para localizar nombres de archivo al instante",
      "syntax": "locate -b '\\sshd_config'; locate -c '*.conf'",
      "flags": [
        {
          "flag": "locate <patrón>",
          "desc": "Busca el patrón en cualquier parte de la ruta completa dentro de la base de datos indexada."
        },
        {
          "flag": "-i, --ignore-case",
          "desc": "🎯 Ignora mayúsculas y minúsculas en la búsqueda."
        },
        {
          "flag": "-b, --basename",
          "desc": "🎯 Clave de Examen: Busca coincidencias ÚNICAMENTE en el nombre final del archivo, ignorando carpetas padre."
        },
        {
          "flag": "-c, --count",
          "desc": "🎯 Muestra únicamente el número total de archivos encontrados."
        },
        {
          "flag": "-e, --existing",
          "desc": "Comprueba si el archivo existe realmente en disco antes de imprimirlo (omite archivos borrados)."
        },
        {
          "flag": "updatedb previo",
          "desc": "🎯 No ve archivos creados después de la última ejecución de updatedb."
        }
      ],
      "examples": [
        "locate -b '\\sshd_config'; locate -c '*.conf'"
      ],
      "exam_tips": [
        {
          "q_num": 5,
          "exam": "101",
          "stem": "Which program updates the database that is used by the locate command? (Specify ONLY the command without any path or parameters).",
          "answer": "updatedb",
          "explanation": "El comando locate consulta una base de datos precompilada de nombres de archivos en lugar de leer el disco en tiempo real. El binario encargado de crear y actualizar dicha base de datos es updatedb ( man 8 updatedb )."
        },
        {
          "q_num": 86,
          "exam": "101",
          "stem": "Which of the following commands can perform searches on file contents using regular expressions?",
          "answer": "grep",
          "explanation": "A diferencia de find y locate (que buscan nombres y metadatos de archivos) o pgrep (que busca procesos), grep ( Global Regular Expression Print ) busca patrones de expresiones regulares dentro del contenido de los archivos."
        }
      ],
