      "tema": "103",
      "subtopic_id": "103.3",
      "title": "Trampa LPI: El flag -f espera inmediatamente el archivo",
      "desc": "En 'tar', la opción '-f' DEBE recibir el nombre del archivo comprimido justo a continuación. 'tar -zcvf archivo.tgz' es correcto; 'tar -fzc archivo.tgz' FALLA porque interpreta 'z' o 'c' como el nombre del archivo.",
