      "title": "Clave Examen: umask nunca da ejecución a archivos",
      "desc": "Para directorios la base inicial es 777 (rwxrwxrwx). Para archivos regulares la base máxima es 666 (rw-rw-rw-), ya que por seguridad nunca se crean archivos con ejecución por defecto.",
