      "label": "🎯 Permisos Especiales: SUID, SGID, Sticky",
      "type": "exam_trap",
      "exam": "101",
      "tema": "104",
      "subtopic_id": "104.5",
      "title": "Clave Examen: Valores octales 4000, 2000, 1000",
      "desc": "SUID = 4 (ejecuta con UID del dueño). SGID = 2 (ejecuta con GID de grupo; en directorios hereda grupo a archivos nuevos). Sticky Bit = 1 (en directorios compartidos como /tmp solo el dueño o root puede borrar su archivo).",
