      "type": "exam_trap",
      "exam": "101",
      "tema": "102",
      "subtopic_id": "102.1",
      "title": "Clave Examen: Parámetros del swap en fstab",
      "desc": "Una línea de swap en /etc/fstab tiene el formato: '/dev/sdb2 none swap sw 0 0' o con UUID. El punto de montaje es 'none' o 'swap', el tipo de sistema es 'swap', opciones 'sw' y los campos dump y fsck son siempre '0 0'.",
